head.script:
scwin.onpageload = function() {
	// 자동 조회
};

/**
 * 함수설명 : 페이지 언로드 시에 수행되는 함수
 */ 
scwin.onpageunload = function() {

};

/**
 * 함수설명 : 페이지 로드 완료 후에 수행되는 함수
 */ 
scwin.onloadcompleted = function() {

};		

/**
 * 함수설명 : 검색 버튼 클릭 이벤트
 */ 
scwin.btn_search_onclick = function(e) {
	scwin.search();
};

/**
 * 함수설명 : 조회 함수
 */ 
scwin.search = function() {
	scwin.$w.executeSubmission(submission1)
};


scwin.search2 = function() {
	scwin.$w.executeSubmission(submission2)
};


scwin.submission1_submitdone = function(e) {
	wfm_wframe1.getWindow().scwin.search();
	scwin.search2();
};

scwin.submission2_submitdone = function(e) {
	wfm_wframe1.setSrc(wfm_wframe1.getSrc());
};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('___processbar2_i').style.display == 'none';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_search').click()");
	WebSquare.wUnit.addCommand("pause", "6500");	
	WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('___processbar2_i').style.display == 'none'", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
